'use strict';const fs=require('fs'),vm=require('vm'),assert=require('assert');const{JSDOM}=require('jsdom');const F='iframe.etymology-source-frame',N='script.anki-final-reviewed-data';
function setup(code,options={}){const dom=new JSDOM('<!doctype html><html><body></body></html>'),w=dom.window,doc=w.document,raf=[],counts={frames:0,native:0,snapshot:0,geometry:0,disconnect:0,takeRecords:0};const query=doc.querySelectorAll.bind(doc);doc.querySelectorAll=function(selector){if(selector===F)counts.frames++;if(selector===N)counts.native++;return query(selector);};let now=0,alive=true,snap=0;Object.defineProperty(doc,'fonts',{value:{status:'loading'}});const RealMO=w.MutationObserver;
if(options.unsupported)Object.defineProperty(w,'MutationObserver',{value:undefined});else Object.defineProperty(w,'MutationObserver',{value:class{constructor(fn){if(options.constructFail)throw Error('MO construct');this.mo=new RealMO(fn);}observe(root,config){if(options.observeFail)throw Error('MO observe');this.mo.observe(root,config);}takeRecords(){counts.takeRecords++;if(options.takeFail)throw Error('MO take');return this.mo.takeRecords();}disconnect(){counts.disconnect++;this.mo.disconnect();}}});
const context={performance:{now:()=>now},requestAnimationFrame:fn=>{if(options.rafFail)throw options.rafFail;raf.push(fn);},snapshot(d,text){counts.snapshot++;assert.equal(d,entry.doc);assert.equal(text,false);return{snapshot:snap};},Array,JSON,Math,Error,Promise};vm.createContext(context);vm.runInContext(code+'\nthis.wait=waitPrepared;',context);const entry={doc,win:{__ankiCigenFrames:{known:new Map()}}},result={settled:false};const rawPromise=context.wait(entry,()=>alive),promise=rawPromise.then(v=>{result.settled=true;result.value=v;},e=>{result.settled=true;result.error=e;});
function tick(){assert(raf.length,'missing RAF');return raf.shift()();}function frame({className='etymology-source-frame',width=20,state}={}){const el=doc.createElement('iframe');el.className=className;el._width=width;el.getBoundingClientRect=()=>{counts.geometry++;if(el._throw)throw el._throw;return{width:el._width};};doc.body.append(el);if(state)entry.win.__ankiCigenFrames.known.set(el,state);return el;}function payload(value='preparing',cls='anki-final-reviewed-data'){const el=doc.createElement('script');el.className=cls;el.dataset.nativeState=value;doc.body.append(el);return el;}
return{dom,w,doc,entry,counts,rawPromise,promise,result,tick,raf,frame,payload,setNow:v=>now=v,cancel:()=>alive=false,setSnapshot:v=>snap=v,close:()=>dom.window.close()};}
async function run(code,name){const rows=[];async function test(label,fn){await fn();rows.push(label);}
await test('unchanged 500 checks then original three stable snapshots',async()=>{const x=setup(code);x.payload();for(let n=0;n<500;n++)x.tick();if(name==='old'){assert.equal(x.counts.frames,500);assert.equal(x.counts.native,500);}else{assert.equal(x.counts.frames,1,'unchanged gate repeated iframe member queries');assert.equal(x.counts.native,1,'unchanged gate repeated native member queries');}x.doc.fonts.status='loaded';x.doc.querySelector('script').dataset.nativeState='ready';x.tick();x.tick();assert.equal(x.result.settled,false);x.tick();await x.promise;assert.equal(x.result.value,true);assert.equal(x.counts.snapshot,3);if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
await test('same-task append/delete/reorder/classes/undelivered records',async()=>{const x=setup(code),first=x.payload();x.tick();const second=x.payload('ready'),state={ready:false,readySignature:'s',signature:'s',readyWidth:20},f=x.frame({state});x.tick();assert.equal(x.result.settled,false);first.className='other';x.doc.fonts.status='loaded';x.tick();x.tick();first.className='anki-final-reviewed-data';x.tick();assert.equal(x.result.settled,false);first.remove();x.tick();f.className='not-cigen';x.tick();f.className='etymology-source-frame';x.tick();f.remove();x.tick();x.tick();x.tick();await x.promise;assert.equal(x.result.value,true);if(name!=='old'){assert(x.counts.takeRecords>0);assert(x.counts.frames>=5);}x.close();});
await test('delivered observer callback invalidates cached arrays',async()=>{const x=setup(code);x.payload();x.tick();await Promise.resolve();x.payload('ready');await Promise.resolve();x.tick();assert.equal(x.result.settled,false);x.cancel();x.tick();await x.promise;assert.equal(x.result.value,false);if(name!=='old')assert.equal(x.counts.native,2);x.close();});
await test('frame error precedes native selector and preserves error identity',async()=>{const x=setup(code),error=Error('child failed');x.frame({state:{error}});x.payload('failed');x.tick();await x.promise;assert.equal(x.result.error,error);assert.equal(x.counts.native,0);if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
await test('native failed message and cleanup',async()=>{const x=setup(code);x.payload('failed');x.tick();await x.promise;assert.equal(x.result.error.message,'Original native validation failed');if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
await test('fresh width/native/child signature/fonts and full stable snapshot',async()=>{const x=setup(code),p=x.payload(),state={ready:false,readySignature:'s',signature:'s',readyWidth:20},f=x.frame({state});x.tick();p.dataset.nativeState='ready';x.doc.fonts.status='loaded';x.tick();state.ready=true;state.readySignature='old';x.tick();state.readySignature='s';f._width=25;x.tick();state.readyWidth=25;x.tick();x.setSnapshot(1);x.tick();x.tick();assert.equal(x.result.settled,false);x.tick();await x.promise;assert.equal(x.result.value,true);assert.equal(x.counts.snapshot,4);if(name!=='old'){assert.equal(x.counts.frames,1);assert.equal(x.counts.native,1);}x.close();});
await test('entry document reuse disconnects old cache and reads new members',async()=>{const x=setup(code);x.payload();x.tick();const next=new JSDOM('<!doctype html><script class="anki-final-reviewed-data" data-native-state="ready"></script>');Object.defineProperty(next.window.document,'fonts',{value:{status:'loaded'}});x.entry.doc=next.window.document;x.tick();x.tick();x.tick();await x.promise;assert.equal(x.result.value,true);if(name!=='old')assert.equal(x.counts.disconnect,1);next.window.close();x.close();});
await test('cancel before first selector does not install observer',async()=>{const x=setup(code);x.cancel();x.tick();await x.promise;assert.equal(x.result.value,false);assert.equal(x.counts.frames,0);assert.equal(x.counts.disconnect,0);x.close();});
await test('cancel after query disconnects',async()=>{const x=setup(code);x.tick();x.cancel();x.tick();await x.promise;assert.equal(x.result.value,false);if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
await test('timeout keeps original error and disconnects',async()=>{const x=setup(code);x.payload();x.tick();x.setNow(10001);x.tick();await x.promise;assert(x.result.error.message.startsWith('Connected original card preparation timed out: '));if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
await test('geometry exception rejects the same promise without escaping rAF and disconnects once',async()=>{const x=setup(code),f=x.frame(),error=Error('geometry');f._throw=error;assert.doesNotThrow(()=>x.tick());await assert.rejects(x.rawPromise,e=>e===error);await x.promise;assert.equal(x.result.settled,true);assert.equal(x.result.error,error);assert.equal(x.raf.length,0);if(name!=='old')assert.equal(x.counts.disconnect,1);x.close();});
if(name!=='old')for(const option of ['unsupported','constructFail','observeFail','takeFail'])await test(option+' falls back to original scan',async()=>{const x=setup(code,{[option]:true});x.payload();for(let n=0;n<6;n++)x.tick();assert.equal(x.counts.frames,6);assert.equal(x.counts.native,6);x.cancel();x.tick();await x.promise;x.close();});
return rows;}
(async()=>{const input=JSON.parse(fs.readFileSync(0,'utf8'));const passed=await run(input.code,'new');console.log(JSON.stringify({passed:true,contracts:passed.length,cases:passed}));})().catch(error=>{console.error(error.stack);process.exitCode=1;});
